class Solution:
    def peopleIndexes(self, favoriteCompanies: List[List[str]]) -> List[int]:
        sets = [set(c) for c in favoriteCompanies]
        res = []
        for i, s in enumerate(sets):
            if not any(len(s) <= len(t) and s <= t for j, t in enumerate(sets) if j != i):
                res.append(i)
        return res

