class Solution {
public:
    vector<int> peopleIndexes(vector<vector<string>>& favoriteCompanies) {
        int n = favoriteCompanies.size();
        vector<unordered_set<string>> sets(n);
        for (int i = 0; i < n; i++)
            sets[i] = unordered_set<string>(favoriteCompanies[i].begin(), favoriteCompanies[i].end());
        vector<int> res;
        for (int i = 0; i < n; i++) {
            bool sub = false;
            for (int j = 0; j < n && !sub; j++) {
                if (i == j || sets[i].size() > sets[j].size()) continue;
                sub = true;
                for (auto& c : favoriteCompanies[i])
                    if (!sets[j].count(c)) { sub = false; break; }
            }
            if (!sub) res.push_back(i);
        }
        return res;
    }
};

