class Solution {
    public List<Integer> peopleIndexes(List<List<String>> favoriteCompanies) {
        int n = favoriteCompanies.size();
        List<Set<String>> sets = new ArrayList<>();
        for (List<String> c : favoriteCompanies) sets.add(new HashSet<>(c));
        List<Integer> res = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            boolean sub = false;
            for (int j = 0; j < n && !sub; j++) {
                if (i == j || sets.get(i).size() > sets.get(j).size()) continue;
                sub = true;
                for (String c : favoriteCompanies.get(i))
                    if (!sets.get(j).contains(c)) { sub = false; break; }
            }
            if (!sub) res.add(i);
        }
        return res;
    }
}

