class Solution:
    def peopleIndexes(self, favoriteCompanies: List[List[str]]) -> List[int]:
        ids = {}
        masks = []
        for comps in favoriteCompanies:
            m = 0
            for c in comps:
                if c not in ids:
                    ids[c] = len(ids)
                m |= 1 << ids[c]
            masks.append(m)
        return [i for i, a in enumerate(masks)
                if not any(a & ~b == 0 for j, b in enumerate(masks) if j != i)]

