class Solution {
public:
    vector<int> peopleIndexes(vector<vector<string>>& favoriteCompanies) {
        unordered_map<string, int> id;
        int n = favoriteCompanies.size();
        vector<bitset<500>> bits(n);
        for (int i = 0; i < n; i++)
            for (auto& c : favoriteCompanies[i]) {
                if (!id.count(c)) id[c] = id.size();
                bits[i][id[c]] = 1;
            }
        vector<int> res;
        for (int i = 0; i < n; i++) {
            bool sub = false;
            for (int j = 0; j < n && !sub; j++)
                if (j != i && (bits[i] & ~bits[j]).none()) sub = true;
            if (!sub) res.push_back(i);
        }
        return res;
    }
};

