class Solution {
    public List<Integer> peopleIndexes(List<List<String>> favoriteCompanies) {
        Map<String, Integer> id = new HashMap<>();
        int n = favoriteCompanies.size();
        BitSet[] bits = new BitSet[n];
        for (int i = 0; i < n; i++) {
            bits[i] = new BitSet();
            for (String c : favoriteCompanies.get(i))
                bits[i].set(id.computeIfAbsent(c, k -> id.size()));
        }
        List<Integer> res = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            boolean sub = false;
            for (int j = 0; j < n && !sub; j++) {
                if (j == i) continue;
                BitSet t = (BitSet) bits[i].clone();
                t.andNot(bits[j]);
                if (t.isEmpty()) sub = true;
            }
            if (!sub) res.add(i);
        }
        return res;
    }
}

